create table if not exists public.deals (id uuid primary key default gen_random_uuid(), offer_id uuid not null references public.offers(id) on delete restrict, connection_id uuid not null references public.connections(id) on delete restrict, buyer_id uuid not null references public.profiles(id) on delete restrict, seller_id uuid not null references public.profiles(id) on delete restrict, source_currency char(3) not null, target_currency char(3) not null, agreed_rate numeric(20,8) not null check(agreed_rate>0), amount numeric(20,2) not null check(amount>0), buyer_confirmed_at timestamptz, seller_confirmed_at timestamptz, status text not null default 'pending' check(status in ('pending','completed','cancelled','disputed')), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), check(buyer_id<>seller_id));
alter table public.deals add column if not exists offer_id uuid; alter table public.deals add column if not exists connection_id uuid; alter table public.deals add column if not exists buyer_id uuid; alter table public.deals add column if not exists seller_id uuid; alter table public.deals add column if not exists source_currency char(3); alter table public.deals add column if not exists target_currency char(3); alter table public.deals add column if not exists agreed_rate numeric(20,8); alter table public.deals add column if not exists amount numeric(20,2); alter table public.deals add column if not exists buyer_confirmed_at timestamptz; alter table public.deals add column if not exists seller_confirmed_at timestamptz; alter table public.deals add column if not exists status text default 'pending'; alter table public.deals add column if not exists created_at timestamptz default now(); alter table public.deals add column if not exists updated_at timestamptz default now();
